// ===============================================
// كاش بسيط للإشعارات في الذاكرة (in-memory)
// ===============================================
// هذا الملف مسؤول عن تخزين عدد الإشعارات لكل مستخدم مؤقتًا في الذاكرة.
// ⚠️ مناسب للتطوير فقط، في الإنتاج يفضل استخدام Redis أو أي تخزين مركزي.

// ===============================================
// كائن Map لتخزين البيانات في الذاكرة
// المفتاح: userId
// القيمة: عدد الإشعارات
const cache = new Map();

// ===============================================
// دالة للحصول على قيمة الإشعارات المخزنة لمستخدم محدد
export function getNotificationCache(userId) {
  return cache.get(userId);
}

// ===============================================
// دالة لتعيين قيمة الإشعارات لمستخدم محدد
export function setNotificationCache(userId, count) {
  cache.set(userId, count);
}

// ===============================================
// دالة لحذف قيمة الإشعارات لمستخدم محدد
export function clearNotificationCache(userId) {
  cache.delete(userId);
}

// ===============================================
// ملاحظات:
// - هذا الكاش يخزن البيانات فقط أثناء تشغيل السيرفر الحالي.
// - عند إعادة تشغيل السيرفر، كل البيانات ستُفقد.
// - في بيئة إنتاجية: استخدم Redis لتخزين مشترك بين كل نسخ السيرفر.
// - هذا الكود مفيد للتجارب أو التطوير المحلي فقط.
// ===============================================
